part1 = """<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0,maximum-scale=1.0,user-scalable=no"><title>TCD PRO TERMINAL</title>
<style>:root{--bg:#0b0e14;--panel:#131722;--bd:#2a2e39;--ac:#2962ff;--gr:#089981;--rd:#f23645;--tx:#d1d4dc;--mu:#787b86}*{box-sizing:border-box}body{font-family:-apple-system,BlinkMacSystemFont,Roboto,sans-serif;background:var(--bg);color:var(--tx);margin:0;padding:8px}.hdr{display:flex;justify-content:space-between;align-items:center;background:var(--panel);padding:9px 12px;border-radius:8px;border:1px solid var(--bd);margin-bottom:8px}.pair{display:flex;align-items:center;gap:8px;font-weight:800;font-size:.95rem;color:#fff}.bal{text-align:right}.bal-v{font-weight:800;color:var(--gr);font-size:.98rem}.bal-s{font-size:.68rem;color:var(--mu)}.nav{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin-bottom:8px}.nb{background:var(--panel);color:var(--mu);border:1px solid var(--bd);padding:8px;border-radius:6px;font-weight:700;font-size:.78rem}.nb.act{background:var(--ac);color:#fff;border-color:var(--ac)}.pnl{display:none}.pnl.act{display:block}.chart-wrap{background:var(--panel);border:1px solid var(--bd);border-radius:8px;padding:8px;margin-bottom:8px}.tf-bar{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px}.tfs{display:flex;gap:4px}.tf{background:#1e222d;color:var(--mu);border:none;padding:5px 10px;border-radius:4px;font-weight:700;font-size:.73rem}.tf.act{background:var(--ac);color:#fff}.ohlc{font-family:monospace;font-size:.69rem;color:var(--mu);margin-bottom:5px}canvas{width:100%;height:320px;background:#0b0e14;border-radius:6px;display:block}.btn-call{background:var(--gr);color:#fff;border:none;padding:13px;border-radius:8px;font-weight:800;font-size:.9rem;width:100%}.btn-put{background:var(--rd);color:#fff;border:none;padding:13px;border-radius:8px;font-weight:800;font-size:.9rem;width:100%}.ia-strip{background:var(--panel);border:1px solid var(--bd);border-radius:8px;padding:10px;display:flex;justify-content:space-between;align-items:center;font-size:.76rem;margin-top:8px}.tag{padding:3px 8px;border-radius:4px;font-weight:800;font-size:.7rem}.t-ok{background:rgba(8,153,129,.2);color:var(--gr)}.t-rd{background:rgba(242,54,69,.2);color:var(--rd)}.card{background:var(--panel);border:1px solid var(--bd);border-radius:8px;padding:12px;margin-bottom:8px}table{width:100%;border-collapse:collapse;font-size:.73rem}th,td{padding:7px 4px;border-bottom:1px solid var(--bd);text-align:left}input{width:100%;padding:10px;border-radius:6px;border:1px solid var(--bd);background:#0b0e14;color:#fff;margin:4px 0 8px 0}</style></head><body>
{% if not auth %}<div class="card" style="max-width:360px;margin:50px auto"><h3 style="margin-top:0;color:#fff">TCD PRO TERMINAL</h3><form method="POST" action="/login"><input type="password" name="pwd" placeholder="Mot de passe" required><button class="btn-call" type="submit">OUVRIR LE TERMINAL</button></form></div>
{% else %}<div class="hdr"><div class="pair"><span>₿ BTC/USDT</span><span class="tag t-ok" id="wsBadge">● LIVE</span></div><div class="bal"><div class="bal-v" id="uV">{{ live.solde_usdt }} $</div><div class="bal-s" id="posV">Pos: {{ "%.5f BTC"|format(pos_active.quantite) if pos_active else "0.00000 BTC" }}</div></div></div>
<div class="nav"><button class="nb act" onclick="tab(0)">📈 Terminal</button><button class="nb" onclick="tab(1)">🧾 Ordres (SHA)</button><button class="nb" onclick="tab(2)">🛡️ Risques</button></div>
<div class="pnl act" id="p0"><div class="chart-wrap"><div class="tf-bar"><div class="tfs"><button class="tf act" onclick="loadTF('1m',60,this)">1M</button><button class="tf" onclick="loadTF('5m',300,this)">5M</button><button class="tf" onclick="loadTF('15m',900,this)">15M</button><button class="tf" onclick="loadTF('1h',3600,this)">1H</button></div><div style="font-family:monospace;font-size:.76rem;color:#fff" id="timerBox">⏱ 01:00</div></div><div class="ohlc" id="ohlcBar">O -- H -- L -- C --</div><canvas id="cv"></canvas></div>
<form method="POST" action="/toggle_cb" style="margin:0">{% if cfg.circuit_breaker_actif=='1' %}<button class="btn-call" type="submit">▶ RÉACTIVER LE ROBOT AUTO (SEUIL 62%)</button>{% else %}<button class="btn-put" type="submit">⏸ ARRÊT D'URGENCE (COUPE-CIRCUIT)</button>{% endif %}</form>
<div class="ia-strip"><div><strong>IA 1H :</strong> <span id="cb">{{ '%.1f'|format(derniere_dec.confiance_brute*100) if derniere_dec else '--' }}%</span> (Cal: <span id="cc">{{ '%.1f'|format(derniere_dec.confiance_calibree*100) if derniere_dec else '--' }}%</span>)</div><span class="tag t-rd" id="reg">{{ derniere_dec.regime if derniere_dec else 'INIT' }}</span></div></div>
<div class="pnl" id="p1"><div class="card"><table><thead><tr><th>Date</th><th>Side</th><th>Qté</th><th>Prix</th><th>SHA-256</th></tr></thead><tbody>{% for o in ordres %}<tr><td>{{ o.date_str }}</td><td><strong>{{ o.side }}</strong></td><td>{{ o.quantite }}</td><td>{{ '%.2f'|format(o.prix) }}$</td><td style="font-family:monospace;color:#2962ff">{{ o.hash_verification }}</td></tr>{% endfor %}</tbody></table><a href="/export/csv?pwd={{ pwd }}"><button class="btn-call" style="margin-top:8px" type="button">⬇ EXPORTER AUDIT CSV</button></a></div></div>
<div class="pnl" id="p2"><div class="card"><form method="POST" action="/save_config"><label style="font-size:.72rem;color:var(--mu)">Mise par trade (USDT)</label><input type="number" step="1" name="mise_usdt" value="{{ cfg.mise_usdt }}"><label style="font-size:.72rem;color:var(--mu)">Seuil IA requis (0.62 = 62%)</label><input type="number" step="0.01" min="0.50" max="0.95" name="seuil_ia" value="{{ cfg.seuil_ia }}"><label style="font-size:.72rem;color:var(--mu)">Take-Profit (0.020 = +2%)</label><input type="number" step="0.001" name="tp_pct" value="{{ cfg.tp_pct }}"><label style="font-size:.72rem;color:var(--mu)">Stop-Loss (0.010 = -1%)</label><input type="number" step="0.001" name="sl_pct" value="{{ cfg.sl_pct }}"><button class="btn-call" type="submit">💾 SAUVEGARDER</button></form></div></div>"""
open("index.html", "w").write(part1)
